import React, { useEffect, useState } from 'react'

import Button from '../../components/Button';
import Header from '../../components/Header';
import Input from '../../components/Input';
import TextArea from '../../components/TextArea';
import { useNavigate } from 'react-router-dom';
import { RegisterWrapper, BodyRegisterContainer, InputRegisterContainer, ButtonWrapper, ButtonContainer, TextAreaContainer, ImageUpload } from './styles';
import ImageUploading, { ImageListType } from "react-images-uploading";
import { BASE_URL } from '../../utils/requests';
import axios, { AxiosRequestConfig } from 'axios';



const Register = () => {

  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [beds, setBeds] = useState('');
  const [baths, setBaths] = useState('');
  const [yearBuilt, setYearBuilt] = useState('');
  const [price, setPrice] = useState('');
  const [sqft, setSqft] = useState('');
  const [address, setAddress] = useState('');
  const [city, setCity] = useState('');
  const [county, setCounty] = useState('');
  const [state, setState] = useState('');
  const [informationLink, setInformationLink] = useState('');
  const [mapLink, setMapLink] = useState('');
  const [images, setImages] = React.useState([]);


  const maxNumber = 8;
  const onChange = (
    imageList: ImageListType,
    addUpdateIndex: number[] | undefined
  ) => {
    // data for submit
    console.log(imageList, addUpdateIndex);
    setImages(imageList as never[]);
  };

  const navigate = useNavigate();


  const handleToRegister = () => {
    
    const data = {
      title,
      description,
      beds,
      baths,
      yearBuilt,
      price,
      sqft,
      address,
      city,
      county,
      state,
      informationLink,
      mapLink,
      images
    }
    const config: AxiosRequestConfig = {
      baseURL: BASE_URL,
      method: 'POST',
      url: '/properties',
      data: { data }
    }
    axios(config).then(response => {
      
      navigate('/dashboard');
    });

  }
  return (
    <RegisterWrapper>
      <Header />
      <h1>Register your land</h1>
      <BodyRegisterContainer>

        <ImageUpload style={{ marginBottom: "2rem" }} >
          <div className="App">
            <ImageUploading
              multiple
              value={images}
              onChange={onChange}
              maxNumber={maxNumber}
            >
              {({
                imageList,
                onImageUpload,
                onImageRemoveAll,
                onImageUpdate,
                onImageRemove,
                isDragging,
                dragProps
              }) => (
                // write your building UI
                <div className="upload__image-wrapper">
                  <button className='button-upload'
                    style={isDragging ? { color: "red" } : undefined}
                    onClick={onImageUpload}
                    {...dragProps}
                  >
                    Click or Drop here
                  </button>
                  &nbsp;
                  <button onClick={onImageRemoveAll}>Remove all images</button>

                  {imageList.map((image, index) => (
                    <div key={index} className="image-item">
                      <img src={image.dataURL} alt="" width="100" />
                      <div className="image-item__btn-wrapper">
                        <button onClick={() => onImageUpdate(index)}>Update</button>
                        <button onClick={() => onImageRemove(index)}>Remove</button>
                      </div>
                    </div>
                  ))}

                </div>
              )}
            </ImageUploading>
          </div>
        </ImageUpload>


        <InputRegisterContainer style={{ marginTop: "70px" }}>
          <Input placeholder='Title*' value={title} onChange={e => setTitle(e.target.value)} />
        </InputRegisterContainer>

        <TextAreaContainer>
          <TextArea placeholder='Description*' value={description} onChange={e => setDescription(e.target.value)} />
        </TextAreaContainer>
        <InputRegisterContainer>
          <Input placeholder='Beds*' value={beds} onChange={e => setBeds(e.target.value)} />
        </InputRegisterContainer>
        <InputRegisterContainer>
          <Input placeholder='Baths*' value={baths} onChange={e => setBaths(e.target.value)} />
        </InputRegisterContainer>
        <InputRegisterContainer>
          <Input placeholder='Yr Built?*' value={yearBuilt} onChange={e => setYearBuilt(e.target.value)} />
        </InputRegisterContainer>
        <InputRegisterContainer style={{ width: "20%" }} >
          <Input placeholder='Price*' value={price} onChange={e => setPrice(e.target.value)} />
        </InputRegisterContainer>
        <InputRegisterContainer>
          <Input placeholder='Sqft*' value={sqft} onChange={e => setSqft(e.target.value)} />
        </InputRegisterContainer>

        <InputRegisterContainer>
          <Input placeholder='Address*' value={address} onChange={e => setAddress(e.target.value)} />
        </InputRegisterContainer>
        <InputRegisterContainer>
          <Input placeholder='City*' value={city} onChange={e => setCity(e.target.value)} />
        </InputRegisterContainer>
        <InputRegisterContainer>
          <Input placeholder='county*' value={county} onChange={e => setCounty(e.target.value)} />
        </InputRegisterContainer>

        <InputRegisterContainer>
          <Input placeholder='State*' value={state} onChange={e => setState(e.target.value)} />
        </InputRegisterContainer>
        <InputRegisterContainer>
          <Input placeholder='Information Link*' value={informationLink} onChange={e => setInformationLink(e.target.value)} />
        </InputRegisterContainer>
        <InputRegisterContainer>
          <Input placeholder='Map Link*' value={mapLink} onChange={e => setMapLink(e.target.value)} />
        </InputRegisterContainer>


      </BodyRegisterContainer>
      <ButtonWrapper>
        <ButtonContainer>
          <Button type='submit' onClick={handleToRegister} style={{ borderRadius: "30px" }}>Register</Button>
        </ButtonContainer>
      </ButtonWrapper>
    </RegisterWrapper>

  )
}

export default Register
